vec3 map(vec3 color) {
    float intensity = max(color.r, max(color.g, color.b));
    intensity = log(intensity + 1.0);
    vec3 white = vec3(1.0);

    // Map intensity through Reinhard or custom curve
    float mappedIntensity = intensity / (intensity + 0.25); // Softer curve

    // Interpolate between original color and white based on intensity
    vec3 result = mix(color, white, smoothstep(1.0, 3.0, intensity));

    // Apply intensity scaling
    return result * mappedIntensity;
}

