void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    // Camera setup - rotating in XZ plane
    float time = iTime * 0.1;
    float radius = 70.0;

    // Center point of the attractor
    vec3 attractorCenter = vec3(0.0, 0.0, 27.0);

    vec3 cameraPos = attractorCenter + vec3(
        radius * cos(time),  // X
        0.0,                 // Fixed at Y=0
        radius * sin(time)   // Z
    );
    vec3 target = attractorCenter;     // Looking at attractor center
    vec3 up = vec3(0.0, 1.0, 0.0);    // Y is up
    mat3 viewMatrix = lookAt(cameraPos, target, up);

    // Adjusted scale for better view
    uv *= 2.0;

    vec3 pos = vec3(0.1 + sin(iTime*10.0), cos(iTime*69.123), 0.0);
    vec3 prev_pos = pos;
    vec3 color = vec3(0.0);
    float dt = 0.01;
    float a = 10.0;
    float b = 28.0;
    float c = 8.0 / 3.0;
    float min_dist = 999999.0;
    vec3 min_pos = pos;
    vec3 min_viewed_pos;  // Store the viewed position for depth coloring
    int num_steps = 400;

    for (int i = 0; i < num_steps; i++) {
        // Lorenz system equations
        vec3 dpos = vec3(
            a * (pos.y - pos.x),
            pos.x * (b - pos.z) - pos.y,
            pos.x * pos.y - c * pos.z
        ) * dt;
        pos += dpos;

        // View transformation - subtract center to normalize around origin
        vec3 viewed_pos = viewMatrix * (pos - attractorCenter) * 0.04;
        vec3 viewed_prev = viewMatrix * (prev_pos - attractorCenter) * 0.04;

        vec2 p = viewed_pos.xy;
        vec2 pa = uv - p;
        vec2 ba = viewed_prev.xy - p;
        float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
        vec2 q = pa - ba * h;
        float dist = dot(q,q);

        if (dist < min_dist) {
            min_dist = dist;
            min_pos = pos;
            min_viewed_pos = viewed_pos;  // Store the viewed position
        }
        prev_pos = pos;
    }
    min_dist = sqrt(min_dist);

    // Color based on view depth (z component after projection)
    vec4 cfg = vec4(0.1, 0.8, 1.0, 1.0);
    vec4 cbg = vec4(1.0, 0.4, 0.1, 1.0);
    float depthFactor = (min_viewed_pos.z + 1.0) * 0.5;  // Normalize depth to 0-1 range
    vec4 cc = mix(cbg, cfg, 1.0 - depthFactor);

    float thickness = 0.02;
    fragColor = (min_dist < thickness ? 
        cc : 
        vec4(0.0)) * 10.0;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;
    vec4 c1 = texture(iChannel0, uv);

    // Gaussian kernel weights (3x3)
    float kernel[9] = float[](
        1.0, 2.0, 1.0,
        2.0, 4.0, 2.0,
        1.0, 2.0, 1.0
    );

    float weightSum = 16.0;  // Sum of the kernel weights

    ivec2 texSize = textureSize(iChannel1, 0);
    ivec2 texCoord = ivec2(fragCoord);

    vec4 c2 = vec4(0.0);

    // Gaussian sampling with texelFetch
    for(int x = -1; x <= 1; x++) {
        for(int y = -1; y <= 1; y++) {
            int idx = (y + 1) * 3 + (x + 1);
            c2 += texelFetch(iChannel1, texCoord + ivec2(x, y), 0) * kernel[idx];
        }
    }

    c2 /= weightSum;  // Normalize by kernel sum

    // Blend the original and blurred images
    fragColor = 0.001 * c1 + 0.998 * c2;
}
